lvlLen = input(20, "High Length", 2, 100, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)
lvl = highest(high, lvlLen)
lvlPrev = lvl[1]
coneSize = 1.0 * markerSize
buySig = crossover(close, lvlPrev)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", coneSize, 0, "3d")
}
